import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_counts_none_as_unflagged():
    assert monitor_flag_rate([{"flagged": None}, {"flagged": True}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_parse_log_skips_comments_and_blanks_and_strips_fields():
    lines = ["", " \t", "  # note", " a , 7 , 0 ", " b , -1 , "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 7, "flagged": False},
        {"id": "b", "day": -1, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,1", "a,x,1"])
def test_parse_errors_report_input_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# header", "a,1,1", " ", bad_line])


def test_dedupe_keeps_last_input_record_and_sorts():
    events = parse_transcript_log(["b,9,1", "c,1,0", "a,2,1", "b,2,0"])
    assert dedupe_transcripts(events) == [events[1], events[2], events[3]]


def test_daily_flag_counts_inclusive_range():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,4,1", "f,5,1"])
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 4, 1) == []


def test_trailing_window_boundaries():
    counts = [2, 1, 3]
    assert flags_in_window(counts, 0) == 0
    assert flags_in_window(counts, 2) == 4
    assert flags_in_window(counts, 4) == 6


def test_summary_weights_transcripts_and_counts_calendar_days():
    groups = {
        "a": parse_transcript_log(["a,1,1", "b,4,0"]),
        "b": parse_transcript_log(["c,2,1"]),
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 2 / 3
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_ranking_and_rates():
    groups = {"z": [{"flagged": True}], "empty": [], "b": [{"flagged": False}], "a": [{"flagged": False}]}
    assert top_flagged_groups(groups, 5) == ["z", "a", "b"]
    assert top_flagged_groups(groups, 2) == ["z", "a"]
    assert list(flag_rate_by_group(groups).items()) == [("a", 0.0), ("b", 0.0), ("empty", None), ("z", 1.0)]


def test_streak_requires_consecutive_positive_counts():
    assert longest_flag_streak([1, 2, 0, 2, -1, 1]) == 2
    assert longest_flag_streak([]) == 0
    assert longest_flag_streak([0, -1]) == 0
